module aes_256 (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [255:0] data_in,
    input wire [255:0] key,
    output reg [255:0] data_out,
    output reg done
);
    // Internal signals and registers
    reg [255:0] state;
    reg [255:0] round_key;
    integer round;

    // AES rounds
    parameter NUM_ROUNDS = 14;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 0;
            round_key <= 0;
            round <= 0;
            data_out <= 0;
            done <= 0;
        end else if (start) begin
            state <= data_in;
            round_key <= key;
            round <= 0;
